#!/bin/bash
#####################################################################################################################
# paradim.sh
# Brief: This script runs the Paramedir configuration on the traces generated by dimemas_traces.sh 
#####################################################################################################################

function run_paradim() {
    run_root=%COMMON_PATH_LOCATIONS.RUN_ROOT%
    project=%COMMON_PATH_LOCATIONS.PROJECT_ROOT%
    analysis_tools=${project}/cfg/trace_analysis/
    model=%MODEL.NAME%
    cfg=%COMMON_PATH_LOCATIONS.CFG%
    platform=%DEFAULT.HPCARCH%
    platform=${platform,,}
    env_sources=${cfg}/env/${platform}/environment.env 
    tests="%TRACING.TEST_NAMES%"

    source ${env_sources}

    member="tracing"
    tests=${tests//[\[,\]]/}
    tests=$(for v in $tests; do echo "$v";done| sort| uniq| xargs)
    paradim_configurations=$(find ${analysis_tools}/paradim_configurations/*)

    for test in $tests
    do
        test_name=${member}/${test}
        cd ${run_root}/${test_name} || exit
        for trace_folder in run_*
        do
            trace=${trace_folder}/${model}.best_cut.prv
            trace_id=${trace_folder//*run_/}
            
            # paramdim.target
            ##################
            dimemas_traces=( dimemas_traces/${trace_id}*.prv )
            for trace in "${dimemas_traces[@]}"
            do
                for cfg in $paradim_configurations
                do
                    paramedir ${trace} ${cfg}
                    output_name=$(basename ${cfg/.cfg/} )
                    new_name=${trace/.prv/}_${output_name}
                    mv ${output_name} ${new_name}
                done
            done
            ##################
        done
    done
}

paradim_enabled=%TRACING.DIMEMAS.ENABLED%
paradim_enabled=${paradim_enabled,,}

${paradim_enabled} && run_paradim